using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using RaceDayAPI.Data;using RaceDayAPI.Models;using System.Security.Claims;namespace RaceDayAPI.Controllers{    [Route("api/[controller]")]    [ApiController]    public class EventsController : ControllerBase    {        private readonly RaceDayDbContext _context;        public EventsController(RaceDayDbContext context)        {            _context = context;        }        // GET: /api/events (public)        [HttpGet]        [AllowAnonymous]        public async Task<IActionResult> GetAllEvents()        {            var events = await _context.Events                .Include(e => e.Categories)                .ToListAsync();            return Ok(events);        }        // GET: /api/events/{id} (public)        [HttpGet("{id}")]        [AllowAnonymous]        public async Task<IActionResult> GetEvent(int id)        {            var ev = await _context.Events                .Include(e => e.Categories)                .FirstOrDefaultAsync(e => e.EventID == id);            if (ev == null) return NotFound("Event not found.");            return Ok(ev);        }        // POST: /api/events (Organiser only)        [HttpPost]        [Authorize(Roles = "Organiser")]        public async Task<IActionResult> CreateEvent([FromBody] CreateEventDto dto)        {            var userId = int.Parse(User.FindFirst(ClaimTypes.NameIdentifier)!.Value);            var organiser = await _context.Organisers.FirstOrDefaultAsync(o => o.UserID == userId);            if (organiser == null) return Forbid();            var ev = new Event            {                OrganiserID = organiser.OrganiserID,                Title = dto.Title,                Description = dto.Description,                EventDate = dto.EventDate,                Location = dto.Location,                Distance = dto.Distance,                EventType = dto.EventType,                MaxParticipants = dto.MaxParticipants,                Status = "Upcoming"            };            _context.Events.Add(ev);            await _context.SaveChangesAsync();            return CreatedAtAction(nameof(GetEvent), new { id = ev.EventID }, ev);        }        // PUT: /api/events/{id} (Organiser owner only)        [HttpPut("{id}")]        [Authorize(Roles = "Organiser")]        public async Task<IActionResult> UpdateEvent(int id, [FromBody] UpdateEventDto dto)        {            var userId = int.Parse(User.FindFirst(ClaimTypes.NameIdentifier)!.Value);            var organiser = await _context.Organisers.FirstOrDefaultAsync(o => o.UserID == userId);            if (organiser == null) return Forbid();            var ev = await _context.Events.FirstOrDefaultAsync(e => e.EventID == id);            if (ev == null) return NotFound("Event not found.");            if (ev.OrganiserID != organiser.OrganiserID) return Forbid();            ev.Title = dto.Title ?? ev.Title;            ev.Description = dto.Description ?? ev.Description;            if (dto.EventDate.HasValue) ev.EventDate = dto.EventDate.Value;            ev.Location = dto.Location ?? ev.Location;            if (dto.Distance.HasValue) ev.Distance = dto.Distance;            ev.EventType = dto.EventType ?? ev.EventType;            if (dto.MaxParticipants.HasValue) ev.MaxParticipants = dto.MaxParticipants;            ev.Status = dto.Status ?? ev.Status;            await _context.SaveChangesAsync();            return NoContent();        }        // DELETE: /api/events/{id} (Organiser owner only)        [HttpDelete("{id}")]        [Authorize(Roles = "Organiser")]        public async Task<IActionResult> DeleteEvent(int id)        {            var userId = int.Parse(User.FindFirst(ClaimTypes.NameIdentifier)!.Value);            var organiser = await _context.Organisers.FirstOrDefaultAsync(o => o.UserID == userId);            if (organiser == null) return Forbid();            var ev = await _context.Events.FirstOrDefaultAsync(e => e.EventID == id);            if (ev == null) return NotFound("Event not found.");            if (ev.OrganiserID != organiser.OrganiserID) return Forbid();            _context.Events.Remove(ev);            await _context.SaveChangesAsync();            return NoContent();        }    }    public class CreateEventDto    {        public string Title { get; set; } = string.Empty;        public string? Description { get; set; }        public DateTime EventDate { get; set; }        public string Location { get; set; } = string.Empty;        public decimal? Distance { get; set; }        public string? EventType { get; set; }        public int? MaxParticipants { get; set; }    }    public class UpdateEventDto    {        public string? Title { get; set; }        public string? Description { get; set; }        public DateTime? EventDate { get; set; }        public string? Location { get; set; }        public decimal? Distance { get; set; }        public string? EventType { get; set; }        public int? MaxParticipants { get; set; }        public string? Status { get; set; }    }}